window.saveWarmups = async function(userId) {
  const warmupsObj = {
    1: document.getElementById('warmup-day-1').value.trim(),
    2: document.getElementById('warmup-day-2').value.trim(),
    3: document.getElementById('warmup-day-3').value.trim(),
    4: document.getElementById('warmup-day-4').value.trim(),
    5: document.getElementById('warmup-day-5').value.trim()
  };

  const { error } = await supaClient
    .from('profiles')
    .update({ warmups: JSON.stringify(warmupsObj) })
    .eq('id', userId);

  if (error) {
    alert('Error al guardar las entradas en calor: ' + error.message);
  } else {
    alert('¡Entradas en calor guardadas con éxito para este alumno!');
    if(userProfile) userProfile.warmups = JSON.stringify(warmupsObj);
  }
}
